-- Preserve existing authorization; evaluate session-only checks once per query.
alter policy production_pointing_sessions_read on public.production_pointing_sessions using (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.dashboard.view')) or (select public.has_permission('production.pointing.view')) or (select public.has_permission('production.reports.view'))));
alter policy production_stage_time_entries_read on public.production_stage_time_entries using (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.pointing.view')) or (select public.has_permission('production.reports.view'))));
alter policy prod_piece_stages_read on public.production_prod_piece_stages using (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.dashboard.view')) or (select public.has_permission('production.prods.view')) or (select public.has_permission('production.pointing.view')) or (select public.has_permission('production.reports.view'))));
alter policy prod_piece_stages_manage on public.production_prod_piece_stages using (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.pointing.perform')) or (select public.has_permission('production.pointing.rollback')) or (select public.has_permission('production.pointing.adjust_time')) or (select public.has_permission('production.prods.manage_pieces')) or (select public.has_permission('production.prods.update_stage')))) with check (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.pointing.perform')) or (select public.has_permission('production.pointing.rollback')) or (select public.has_permission('production.pointing.adjust_time')) or (select public.has_permission('production.prods.manage_pieces')) or (select public.has_permission('production.prods.update_stage'))));
alter policy prod_pieces_read on public.production_prod_pieces using (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.dashboard.view')) or (select public.has_permission('production.prods.view')) or (select public.has_permission('production.pointing.view')) or (select public.has_permission('production.reports.view')) or (select public.has_permission('production.prods.import_pieces'))));
alter policy prod_pieces_manage on public.production_prod_pieces using (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.prods.manage_pieces')) or (select public.has_permission('production.prods.import_pieces')))) with check (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.prods.manage_pieces')) or (select public.has_permission('production.prods.import_pieces'))));
alter policy expedition_archives_read on public.production_expedition_archives using (company_id = (select public.current_company_id()) and ((select public.is_master()) or (select public.has_permission('production.pointing.view')) or (select public.has_permission('production.prods.view')) or (select public.has_permission('production.pointing.perform')) or (select public.has_permission('production.prods.manage_pieces'))));
